export type FamilyTree = Record<string, string[]>;

export function degreesOfSeparation(familyTree: FamilyTree, personA: string, personB: string): number {
  if (personA === personB) return 0;

  const visited = new Set<string>();
  const queue: [string, number][] = [[personA, 0]];

  while (queue.length > 0) {
    const [current, distance] = queue.shift()!;
    visited.add(current);

    for (const parent of familyTree[current] || []) {
      if (parent === personB) return distance + 1;
      if (!visited.has(parent)) {
        queue.push([parent, distance + 1]);
      }
    }

    for (const child of familyTree[current] || []) {
      if (child === personB) return distance + 1;
      if (!visited.has(child)) {
        queue.push([child, distance + 1]);
      }
    }
  }

  return -1; // No known relationship
}
